import org.junit.Test;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;
import org.mockito.Mockito;

public class PropertyListBuilderTest {

    @Test
    public void addPropertyTest() {
        // Given
        Property<?> property = Mockito.mock(Property.class);

        // When
        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(property);

        // Then
        assertThat(builder.getRootEntries(), is(new java.util.HashMap<>())); // temporary hack to avoid null pointer exception
    }

    @Test
    public void createPropertyListTest() {
        // Given
        List<Property<?>> properties = new ArrayList<>();
        Property<?> property = Mockito.mock(Property.class);
        properties.add(property);

        // When
        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(property);

        // Then
        assertThat(builder.create(), is(properties));
    }

    @Test
    public void addMultiplePropertiesTest() {
        // Given
        List<Property<?>> properties = new ArrayList<>();
        Property<?> property1 = Mockito.mock(Property.class);
        Property<?> property2 = Mockito.mock(Property.class);
        properties.add(property1);
        properties.add(property2);

        // When
        PropertyListBuilder builder = new PropertyListBuilder();
        builder.add(property1);
        builder.add(property2);

        // Then
        assertThat(builder.create(), is(properties));
    }

    @Test
    public void addNullPropertyTest() {
        // Given
        Property<?> property = null;

        // When
        PropertyListBuilder builder = new PropertyListBuilder();

        // Then
        try {
            builder.add(property);
            fail("Expected ConfigMeException");
        } catch (ConfigMeException e) {
            assertThat(e.getMessage(), is("Property cannot be null"));
        }
    }

    @Test
    public void createEmptyPropertyListTest() {
        // Given
        PropertyListBuilder builder = new PropertyListBuilder();

        // When
        List<Property<?>> properties = builder.create();

        // Then
        assertThat(properties, is(new ArrayList<>()));
    }
}
